{
  "meta": {
    "template": "differentiated-lesson",
    "age": "pro",
    "color": "teal",
    "title": "درس: حل المعادلات من الدرجة الأولى",
    "subtitle": "وفق التعليم المتمايز",
    "banner": "تعليم يتنوع ليلبي احتياجات كل متعلم .. ويقود إلى تعلم فعّال",
    "pageTitle": "درس: حل المعادلات من الدرجة الأولى",
    "formula": {
      "lines": [
        "ax + b = c",
        "x = (c − b) ÷ a"
      ],
      "icon": "💡"
    },
    "art": "📚"
  },
  "info": [
    {
      "icon": "target",
      "label": "الفئة المستهدفة",
      "value": "الصف الأول المتوسط"
    },
    {
      "icon": "calendar",
      "label": "الزمن",
      "value": "حصتان (90 دقيقة)"
    },
    {
      "icon": "level",
      "label": "المادة",
      "value": "رياضيات"
    },
    {
      "icon": "book",
      "label": "الموضوع",
      "value": "حل المعادلات من الدرجة الأولى"
    }
  ],
  "goals": {
    "title": "الأهداف",
    "icon": "target",
    "color": "green",
    "groups": [
      {
        "icon": "book",
        "title": "معرفية",
        "items": [
          "يتعرف مفهوم المعادلة من الدرجة الأولى.",
          "يحدد خطوات حل المعادلات من الدرجة الأولى."
        ]
      },
      {
        "icon": "pencil",
        "title": "مهارية",
        "items": [
          "يحل معادلات من الدرجة الأولى بخطوات صحيحة.",
          "يوظف الحل في مواقف حياتية بسيطة."
        ]
      },
      {
        "icon": "heart",
        "title": "وجدانية",
        "items": [
          "يُظهر دافعية للمشاركة والتعلم.",
          "يقدر أهمية الرياضيات في الحياة اليومية."
        ]
      }
    ]
  },
  "strategies": {
    "title": "استراتيجيات التعليم المتمايز",
    "icon": "puzzle",
    "color": "teal",
    "items": [
      "التعلم حسب مستوى الاستعداد",
      "تنويع المحتوى والأنشطة",
      "تنويع طرق العرض والشرح",
      "التعلم التعاوني",
      "التقويم المستمر والتغذية الراجعة"
    ]
  },
  "tools": {
    "title": "الوسائل التعليمية",
    "icon": "computer",
    "color": "blue",
    "items": [
      "عروض تفاعلية (بوربوينت)",
      "بطاقات تعليمية ملونة",
      "أوراق عمل متدرجة",
      "سبورة ذكية",
      "تطبيقات تعليمية"
    ]
  },
  "homework": {
    "title": "الواجب المنزلي المتمايز",
    "icon": "notebook",
    "color": "yellow",
    "items": [
      {
        "level": "advanced",
        "icon": "🧑‍🎓",
        "label": "المجموعة المتقدمة",
        "text": "مسائل إضافية وتحدي. ابحث عن تطبيقات للمعادلات."
      },
      {
        "level": "middle",
        "icon": "🧑",
        "label": "المجموعة المتوسطة",
        "text": "حل ورقة عمل متدرجة. مسائل من الكتاب المدرسي."
      },
      {
        "level": "basic",
        "icon": "👶",
        "label": "المجموعة الأساسية",
        "text": "ورقة عمل مبسطة. مشاهدة فيديو تعليمي قصير."
      }
    ]
  },
  "groups": {
    "title": "تقسيم المجموعات وفق التعليم المتمايز",
    "icon": "users",
    "items": [
      {
        "level": "basic",
        "name": "المجموعة الأساسية",
        "icon": "user",
        "items": [
          "تمتلك استعداداً منخفضاً.",
          "تحتاج إلى دعم كبير ومستمر.",
          "تحتاج إلى أنشطة مبسطة وخطوات إرشادية واضحة."
        ]
      },
      {
        "level": "middle",
        "name": "المجموعة المتوسطة",
        "icon": "users",
        "items": [
          "تمتلك استعداداً متوسطاً.",
          "تحتاج إلى دعم وتوجيه.",
          "تحتاج إلى أنشطة تطبيقية متدرجة الصعوبة."
        ]
      },
      {
        "level": "advanced",
        "name": "المجموعة المتقدمة",
        "icon": "user-check",
        "items": [
          "تمتلك استعداداً مرتفعاً.",
          "تسعى للتحدي والبحث.",
          "تحتاج إلى أنشطة إثرائية ومسائل غير روتينية."
        ]
      }
    ]
  },
  "intro": {
    "title": "تمهيد (5 دقائق)",
    "icon": "star",
    "color": "yellow",
    "art": "📚",
    "text": "عرض موقف حياتي: اشتريت كتاباً ثمنه «س»، ودفعت مبلغ 25، وكان الباقي 10، ما المعادلة التي تمثل الموقف؟ وما قيمة «س»؟",
    "equation": "س + 10 = 25"
  },
  "activities": {
    "title": "الأنشطة التعليمية المتمايزة (60 دقيقة)",
    "icon": "puzzle",
    "color": "purple",
    "columns": [
      {
        "level": "basic",
        "title": "أنشطة المجموعة الأساسية",
        "items": [
          "حل معادلات بخطوة واحدة.",
          "استخدام بطاقات خطوات الحل.",
          "العمل مع المعلم بشكل مباشر."
        ],
        "example": {
          "icon": "🙋",
          "label": "مثال:",
          "text": "x + 7 = 12"
        }
      },
      {
        "level": "middle",
        "title": "أنشطة المجموعة المتوسطة",
        "items": [
          "حل معادلات من خطوتين.",
          "مسائل تطبيقية بسيطة.",
          "العمل في مجموعات تعاونية لمناقشة الحل."
        ],
        "example": {
          "icon": "👥",
          "label": "مثال:",
          "text": "2x + 5 = 17"
        }
      },
      {
        "level": "advanced",
        "title": "أنشطة المجموعة المتقدمة",
        "items": [
          "حل معادلات تحتوي على كسور وأقواس.",
          "مسائل تطبيقية من واقع الحياة.",
          "تحدي: صمم معادلة وحلها لزميلك."
        ],
        "example": {
          "icon": "🏆",
          "label": "مثال:",
          "text": "3(x − 2) + 4 = 2x + 10"
        }
      }
    ]
  },
  "assessment": {
    "title": "التقويم المتمايز (20 دقيقة)",
    "icon": "clipboard-check",
    "color": "teal",
    "columns": [
      {
        "level": "basic",
        "title": "تقويم المجموعة الأساسية",
        "icon": "user",
        "text": "مسائل بخطوة واحدة مع توجيه مباشر.",
        "example": {
          "label": "مثال:",
          "text": "x − 6 = 9"
        }
      },
      {
        "level": "middle",
        "title": "تقويم المجموعة المتوسطة",
        "icon": "users",
        "text": "مسائل من خطوتين مع دعم حل بعض الخطوات.",
        "example": {
          "label": "مثال:",
          "text": "3x − 4 = 14"
        }
      },
      {
        "level": "advanced",
        "title": "تقويم المجموعة المتقدمة",
        "icon": "trophy",
        "text": "مسائل مركبة وتطبيقات حياتية تتطلب تفكيراً عالياً.",
        "example": {
          "label": "أوجد قيمة س:",
          "text": "4(x + 3) − 2 = 2(x − 1) + 8"
        }
      }
    ]
  },
  "closing": [
    {
      "icon": "check",
      "title": "الخاتمة (5 دقائق)",
      "deco": "🎉",
      "color": "teal",
      "items": [
        "مراجعة سريعة لأهم النقاط.",
        "تشجيع المتعلمين وتقدير جهودهم."
      ],
      "note": "سؤال ختامي: ما الخطوة التي ساعدتك أكثر في حل المعادلة؟"
    },
    {
      "icon": "users",
      "title": "دعم إضافي للمتعثرين",
      "deco": "🌱",
      "color": "blue",
      "items": [
        "إعادة شرح مبسط مع مخططات توضيحية.",
        "استخدام أمثلة قريبة من واقعهم.",
        "وقت إضافي وممارسة موجهة."
      ]
    },
    {
      "icon": "star",
      "title": "إثراءات للمتقدمين",
      "deco": "🎯",
      "color": "red",
      "items": [
        "مسائل تحدٍّ ومسابقات رياضية.",
        "ربط المعادلات بالجبر والهندسة.",
        "استخدام استراتيجيات متنوعة للحل."
      ]
    }
  ]
}

